317	
318	            .append("id", this.getId())
319	            .append("new", this.isNew())
320	            .append("lastName", this.getLastName())
321	            .append("firstName", this.getFirstName())
322	            .append("address", this.address)
323	            .append("city", this.city)
324	            .append("telephone", this.telephone)
325	            .append("email", this.email)
326	            .toString();
327	    }
