8	/**
9	 * Assigns the new owner's {@code membershipLevel}, applying the household level ceiling: a new owner's
10	 * membershipLevel cannot exceed one above the current maximum membershipLevel among their existing
11	 * household members — the owners already persisted that share this owner's {@code householdId}. With
12	 * no existing household member the level derived from points stands uncapped.
13	 *
14	 * <p>Runs after {@link AssignHouseholdId}, {@link AssignHouseholdMemberCount} and
15	 * {@link AssignNamesakeCount} have populated the fields the derived level reads, and before
16	 * {@link SaveOwner}, within the write transaction so the household maximum reflects only owners
17	 * already persisted (excluding this new, not-yet-saved one). The capped value is stored on the entity
18	 * so it is returned by the create response and later reads (see
19	 * {@link OwnerMapper#membershipLevel(Owner)}).
20	 *
21	 * <p>Each existing member's level is evaluated against the household's <em>current</em> size (this
22	 * owner's {@code householdMemberCount}, which already counts the new member): a member's own stored
23	 * household count is frozen at its own create time, so a household that has since grown would otherwise
24	 * understate the members' levels and cap the newcomer too low.
25	 */
26	public class AssignMembershipLevel {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        Integer householdSize = owner.getHouseholdMemberCount();
30	        int derived = OwnerMapper.derivedMembershipLevel(owner);
31	        String householdId = owner.getHouseholdId();
32	        Integer householdMax = null;
33	        if (householdId != null) {
34	            for (Owner existing : ownerRepository.findAll()) {
35	                if (householdId.equals(existing.getHouseholdId())) {
36	                    int level = OwnerMapper.derivedMembershipLevel(existing, householdSize);
37	                    if (householdMax == null || level > householdMax) {
38	                        householdMax = level;
39	                    }
40	                }
41	            }
42	        }
43	        int capped = householdMax == null ? derived : Math.min(derived, householdMax + 1);
44	        owner.setMembershipLevel(capped);
45	    }
46	}
