1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
8	
9	/**
10	 * Rejects a create-owner request whose city already contains 50 or more owners, so the escalation
11	 * handler can respond 409. City is compared case-insensitively, matching how {@link AssignCustomerCode}
12	 * counts a city's owners. Runs within the same write transaction as the insert so the count reflects
13	 * only owners already persisted (excluding this new, not-yet-saved one), giving each city a hard cap
14	 * of 50 owners.
15	 */
16	public class CheckCityCapacity {
17	
18	    private static final int CAPACITY = 50;
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws CityAtCapacityException {
22	        String city = request.getCity();
23	        int count = 0;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
26	                count++;
27	            }
28	        }
29	        if (count >= CAPACITY) {
30	            throw new CityAtCapacityException(city);
31	        }
32	    }
33	}
